function dBy(id){return DRIVERS.find(d=>d.id===id)}
function photo(d){
  const mediaTeam={
    'Mercedes':'mercedes','Ferrari':'ferrari','McLaren':'mclaren',
    'Red Bull Racing':'redbullracing','Racing Bulls':'racingbulls',
    'Alpine':'alpine','Haas':'haas','Audi':'audi','Williams':'williams',
    'Aston Martin':'astonmartin','Cadillac':'cadillac'
  }[d.team]||d.team.toLowerCase().replaceAll(' ','');
  return `https://media.formula1.com/image/upload/c_fill,w_1600/q_auto/v1740000001/common/f1/2026/${mediaTeam}/${d.image}/2026${mediaTeam}${d.image}right.webp`;
}
function teamLogo(team){return LOGOS[team]||''}
function teamCar(team){return CAR_IMAGES[team]||''}
function teamMark(team){
  return `<img src="${teamLogo(team)}" alt="${team} logo" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"><span class="logo-fallback">${team.split(' ').map(x=>x[0]).join('').slice(0,3)}</span>`;
}
function carFallbackMarkup(team){
  const c=TEAM_COLORS[team]||'#333';
  return `<svg class="team-car-fallback" viewBox="0 0 900 240" aria-hidden="true"><g fill="none" stroke="rgba(255,255,255,.48)" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"><path d="M95 169h115l55-44 181-21 83 11 82 38h125"/><path d="M278 125l61-50h116l65 42"/><path d="M516 117l83 13 81 39"/><circle cx="222" cy="169" r="48"/><circle cx="654" cy="169" r="48"/></g><path d="M325 107h150l48 18-76 17H286z" fill="rgba(255,255,255,.12)"/><text x="450" y="222" text-anchor="middle" fill="rgba(255,255,255,.28)" font-family="DM Sans, sans-serif" font-size="18" letter-spacing="7">2026 CHALLENGER</text></svg>`;
}
function go(route,id){
  closeMenu(); transition.classList.remove('active'); void transition.offsetWidth; transition.classList.add('active');
  setTimeout(()=>{ route==='home'?home():route==='teams'?teamsPage():route==='team'?teamPage(id):route==='drivers'?driversPage():route==='driver'?driverPage(id):archivePage(route,id); window.scrollTo(0,0); },410);
}
function openMenu(){menuButton.classList.add('open');topMenu.classList.add('open');menuButton.setAttribute('aria-expanded','true')}
function closeMenu(){menuButton.classList.remove('open');topMenu.classList.remove('open');menuButton.setAttribute('aria-expanded','false')}
menuButton.onclick=()=>topMenu.classList.contains('open')?closeMenu():openMenu();
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();document.getElementById('carCompareOverlay')?.classList.remove('open')}});
document.querySelectorAll('.menu-link').forEach(b=>b.onclick=()=>go(b.dataset.route));

function home(){
 app.innerHTML=`<section class="hero"><div class="hero-grid"><div><div class="eyebrow">A VISUAL INDEX OF FORMULA 1 / 2026</div><h1>THE<br><em>GRID</em></h1></div><div class="hero-copy">Twenty-two drivers. Eleven teams. One season in motion. Explore the people behind the numbers — their routes into Formula 1, their teams, and the careers that brought them here.</div></div><div class="hero-number">26</div><div class="hero-rule"></div><div class="hero-bottom"><span>11 TEAMS · 22 DRIVERS</span><button id="exploreBtn">Explore the grid ↗</button><span>2026 SEASON</span></div></section>`;
 document.getElementById('exploreBtn').onclick=()=>go('teams');
}

function teamsPage(){
 const entries=Object.entries(TEAMS);
 app.innerHTML=`<section class="page"><div class="page-head"><h2 class="page-title">Teams</h2><div class="page-note">THE 2026 GRID<br>11 CONSTRUCTORS</div></div><div class="team-grid">${entries.map(([team,ids])=>`<button class="team-card team-card--showcase" data-team="${team}" style="--team:${TEAM_COLORS[team]}"><div class="team-bg" style="background:${TEAM_COLORS[team]}"></div><div class="team-logo-wrap">${teamMark(team)}</div><span class="team-arrow">↗</span><div class="team-car-stage"><div class="team-car-halo"></div><img class="team-car-cutout" src="${teamCar(team)}" alt="${team} 2026 car" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"><div class="team-car-fallback-wrap">${carFallbackMarkup(team)}</div></div><div class="team-info"><div class="team-name">${team}</div><div class="team-drivers">${ids.map(x=>dBy(x).name).join(' · ')}</div></div></button>`).join('')}</div></section>`;
 document.querySelectorAll('.team-card').forEach(c=>c.onclick=()=>go('team',c.dataset.team));
}

function teamPage(team){
 const ids=TEAMS[team], s=TEAM_STATS[team];
 app.innerHTML=`<section class="page team-page"><button class="back" id="backTeams">← All teams</button><div class="team-hero"><div><div class="page-kicker">TEAM / 2026</div><div class="team-title-row"><img class="team-hero-logo" src="${teamLogo(team)}" onerror="this.style.display='none'"><h1 class="page-title">${team}</h1></div><p class="team-lede">${s.history}</p></div><div class="team-identity"><span>FIRST ENTRY</span><strong>${s.first}</strong><span>BASE</span><strong>${s.base}</strong></div></div>
 <div class="team-options"><button data-view="history"><b>01</b><span>Team history</span><small>Origins · titles · legacy ↗</small></button><button data-view="drivers"><b>02</b><span>Drivers</span><small>${ids.map(x=>dBy(x).name).join(' · ')} ↗</small></button><button data-view="season"><b>03</b><span>2026 season</span><small>Wins · podiums · poles · points ↗</small></button></div>
 <div id="teamDetail"></div></section>`;
 document.getElementById('backTeams').onclick=()=>go('teams');
 document.querySelectorAll('.team-options button').forEach(b=>b.onclick=()=>showTeamView(team,b.dataset.view));
 showTeamView(team,'history');
}

function showTeamView(team,view){
 const s=TEAM_STATS[team], ids=TEAMS[team], box=document.getElementById('teamDetail');
 document.querySelectorAll('.team-options button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 if(view==='history') box.innerHTML=`<div class="detail-panel"><div class="detail-label">THE STORY</div><h3>From first entry to the modern grid.</h3><p>${s.history}</p><div class="stats-grid"><div><span>GRANDS PRIX</span><strong>${s.entered}</strong></div><div><span>WINS</span><strong>${s.wins}</strong></div><div><span>PODIUMS</span><strong>${s.podiums}</strong></div><div><span>POLE POSITIONS</span><strong>${s.poles}</strong></div><div><span>WORLD CHAMPIONSHIPS</span><strong>${s.titles}</strong></div><div><span>BEST FINISH</span><strong>1st</strong></div></div><div class="team-meta"><span>TEAM CHIEF <b>${s.chief}</b></span><span>POWER UNIT <b>${s.power}</b></span><span>CHASSIS <b>${s.chassis}</b></span></div></div>`;
 else if(view==='drivers') box.innerHTML=`<div class="driver-pair compact">${ids.map(id=>{const d=dBy(id);return `<button class="driver-card" data-driver="${d.id}"><img src="${photo(d)}" alt="${d.name}" onerror="this.style.opacity=.15"><div class="driver-info"><div class="driver-first">${d.first} · #${d.number}</div><div class="driver-last">${d.last}</div></div><div class="driver-no">${d.number}</div></button>`}).join('')}</div><div class="driver-note">Select a driver to open the full career dossier.</div>`;
 else box.innerHTML=`<div class="detail-panel"><div class="detail-label">2026 SEASON</div><h3>${s.pos} · ${s.seasonPoints} points</h3><div class="stats-grid"><div><span>RACE WINS</span><strong>${s.seasonWins}</strong></div><div><span>RACE PODIUMS</span><strong>${s.seasonPodiums}</strong></div><div><span>POLES</span><strong>${s.seasonPoles}</strong></div><div><span>TEAM POINTS</span><strong>${s.seasonPoints}</strong></div><div><span>CAREER WINS</span><strong>${s.wins}</strong></div><div><span>CAREER POLES</span><strong>${s.poles}</strong></div></div></div>`;
 box.querySelectorAll('[data-driver]').forEach(c=>c.onclick=()=>go('driver',c.dataset.driver));
}

function driversPage(){
 app.innerHTML=`<section class="page"><div class="page-head"><h2 class="page-title">Drivers</h2><div class="page-note">22 PEOPLE<br>ONE GRID</div></div><div class="team-grid">${DRIVERS.map(d=>`<button class="team-card driver-list-card" data-driver="${d.id}"><div class="driver-list-photo"><img src="${photo(d)}" alt="${d.name}" onerror="this.style.opacity=.2"></div><div class="team-info"><div class="team-name">${d.name}</div><div class="team-drivers">${d.team} · #${d.number}</div></div></button>`).join('')}</div></section>`;
 document.querySelectorAll('[data-driver]').forEach(c=>c.onclick=()=>go('driver',c.dataset.driver));
}

const DRIVER_CHAMPIONSHIPS = {"lewis-hamilton": [2008, 2014, 2015, 2017, 2018, 2019, 2020], "lando-norris": [2025], "max-verstappen": [2021, 2022, 2023, 2024], "fernando-alonso": [2005, 2006]};
const LEGEND_CHAMPIONSHIPS = {"senna": [1988, 1990, 1991], "schumacher": [1994, 1995, 2000, 2001, 2002, 2003, 2004], "fangio": [1951, 1954, 1955, 1956, 1957], "prost": [1985, 1986, 1989, 1993], "lauda": [1975, 1977, 1984], "stewart": [1969, 1971, 1973], "clark": [1963, 1965], "mansell": [1992], "hakkinen": [1998, 1999], "vettel": [2010, 2011, 2012, 2013], "alonso": [2005, 2006], "hamilton": [2008, 2014, 2015, 2017, 2018, 2019, 2020]};

function driverPage(id){
 const d=dBy(id), s=d.stats, team=Object.entries(TEAMS).find(([,ids])=>ids.includes(id))?.[0]||d.team;
 app.innerHTML=`<section class="profile"><div class="profile-visual"><button class="back" id="backTeam">← ${team}</button><img src="${photo(d)}" alt="${d.name}" onerror="this.style.opacity=.18"><div class="profile-number">${d.number}</div></div><article class="profile-content"><div class="profile-kicker">${d.team.toUpperCase()} · DRIVER #${d.number}</div><h1 class="profile-name">${d.first}<br><em>${d.last}</em></h1><p class="profile-intro">${d.bio}</p>
 <div class="meta-grid"><div class="meta"><label>DATE OF BIRTH</label><strong>${d.dob}</strong></div><div class="meta"><label>F1 DEBUT</label><strong>${d.debut}</strong></div><div class="meta"><label>NATIONALITY</label><strong>${d.nationality}</strong></div><div class="meta"><label>CURRENT TEAM</label><strong>${d.team}</strong></div><div class="meta"><label>CAR NUMBER</label><strong>#${d.number}</strong></div><div class="meta"><label>F1 TEAMS</label><strong>${d.route}</strong></div></div>
 <section class="career-stats"><div class="section-label">CAREER RECORD</div><div class="stats-grid"><div><span>GRANDS PRIX</span><strong>${s.starts}</strong></div><div><span>WINS</span><strong>${s.wins}</strong></div><div><span>PODIUMS</span><strong>${s.podiums}</strong></div><div><span>POLE POSITIONS</span><strong>${s.poles}</strong></div><div><span>WORLD CHAMPIONSHIPS</span><strong>${s.titles}</strong></div><div><span>CAREER POINTS</span><strong>${s.points}</strong></div><div><span>HIGHEST FINISH</span><strong>${s.best}</strong></div><div><span>DNFs</span><strong>${s.dnfs}</strong></div></div></section>
 <section class="career-stats season-mini"><div class="section-label">2026 SO FAR</div><div class="stats-grid"><div><span>POSITION</span><strong>${seasonPosition(d)}</strong></div><div><span>POINTS</span><strong>${seasonPoints(d)}</strong></div><div><span>RACE WINS</span><strong>${seasonWins(d)}</strong></div><div><span>RACE PODIUMS</span><strong>${seasonPodiums(d)}</strong></div><div><span>POLES</span><strong>${seasonPoles(d)}</strong></div><div><span>DNFs</span><strong>${seasonDnfs(d)}</strong></div></div></section>
 ${DRIVER_CHAMPIONSHIPS[d.id]?.length ? `<section class="championship-cabinet"><div class="section-label">WORLD CHAMPIONSHIPS</div><div class="championship-years">${DRIVER_CHAMPIONSHIPS[d.id].map(y=>`<span class="championship-year">${y}</span>`).join('')}</div></section>` : ''}
 <div class="profile-footer"><span>THE GRID / 2026</span><span>CAREER DOSSIER</span></div></article></section>`;
 document.getElementById('backTeam').onclick=()=>go('team',team);
}
function teamFor(d){return TEAM_STATS[d.team]||{}}
