function seasonPoints(d){const map={'kimi-antonelli':267,'george-russell':201,'lewis-hamilton':191,'lando-norris':171,'charles-leclerc':155,'max-verstappen':127,'oscar-piastri':116,'isack-hadjar':71,'liam-lawson':51,'pierre-gasly':41,'arvid-lindblad':29,'franco-colapinto':21,'oliver-bearman':18,'gabriel-bortoleto':10,'nico-hulkenberg':6,'carlos-sainz':6,'alexander-albon':5,'esteban-ocon':3,'fernando-alonso':3,'lance-stroll':0,'valtteri-bottas':0,'sergio-perez':0};return map[d.id]??'—'}
function seasonWins(d){const map={'kimi-antonelli':7,'george-russell':2,'lewis-hamilton':1,'lando-norris':2,'charles-leclerc':1};return map[d.id]||0}
function seasonPodiums(d){const map={'kimi-antonelli':11,'george-russell':7,'lewis-hamilton':5,'lando-norris':4,'charles-leclerc':4,'max-verstappen':5,'oscar-piastri':2,'isack-hadjar':1};return map[d.id]||0}
function seasonPoles(d){const map={'kimi-antonelli':6,'george-russell':4,'lando-norris':2,'pierre-gasly':1};return map[d.id]||0}
function seasonDnfs(d){const map={'kimi-antonelli':1,'george-russell':2,'lewis-hamilton':0,'lando-norris':0,'charles-leclerc':3,'max-verstappen':4,'oscar-piastri':1,'isack-hadjar':2,'liam-lawson':1,'pierre-gasly':1,'arvid-lindblad':0,'franco-colapinto':0,'oliver-bearman':4,'gabriel-bortoleto':0,'nico-hulkenberg':0,'carlos-sainz':2,'alexander-albon':3,'esteban-ocon':1,'fernando-alonso':5,'lance-stroll':8,'valtteri-bottas':6,'sergio-perez':0};return map[d.id]??'—'}

