function archiveTransition(render){
  if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ render(); window.scrollTo(0,0); return; }
  app.classList.remove('archive-enter');
  app.classList.add('archive-exit');
  window.setTimeout(()=>{
    render();
    window.scrollTo(0,0);
    app.classList.remove('archive-exit');
    app.classList.add('archive-enter');
    requestAnimationFrame(()=>requestAnimationFrame(()=>app.classList.remove('archive-enter')));
  },260);
}
function archiveInit(){
  document.querySelectorAll('.menu-link').forEach(b=>b.onclick=()=>go(b.dataset.route));
}
function archivePage(route,id){
 const pages={legends:['Legends / Icons','The drivers who shaped the sport.'],rivalries:['Rivalries','The battles that became bigger than the races.'],cars:['Iconic Cars','Machines that changed what an F1 car could be.'],eras:['Eras','A visual timeline through 75+ years of Formula 1.'],races:['Greatest Races','The races people still talk about.'],champions:['Champions','Every Drivers’ World Champion, 1950–2026.'], 'historic-teams':['Historic Teams','Constructors that built the sport before today’s grid.'],records:['Records','The numbers that define Formula 1.'],moments:['Iconic Moments','The seconds, laps and seasons that became mythology.']};
 if(route==='legends') return legendsPage();
 if(route==='rivalries') return archiveListPage(pages[route],RIVALRIES,'rivalry');
 if(route==='cars') return carsPage();
 if(route==='eras') return archiveListPage(pages[route],ERAS,'era');
 if(route==='races') return archiveListPage(pages[route],RACES,'race');
 if(route==='champions') return championsPage();
 if(route==='historic-teams') return archiveListPage(pages[route],HISTORIC_TEAMS,'historic');
 if(route==='records') return recordsPage();
 if(route==='moments') return archiveListPage(pages[route],MOMENTS,'moment');
}
function archiveShell(title,note,body){
 app.innerHTML=`<section class="page archive-page"><div class="page-head"><h2 class="page-title">${title}</h2><div class="page-note">${note}</div></div>${body}</section>`;
}
function legendsPage(){
 archiveShell('Legends / Icons','F1 HALL OF FAME · SELECTED GREATS',`<div class="legend-grid">${LEGENDS.map((x,i)=>`<button class="legend-card" data-legend="${x.id}"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="legend-tag">${x.tag}</div><h3>${x.name}</h3><div class="legend-years">${x.years}</div><p>${x.text}</p><div class="legend-stats"><span><b>${x.titles}</b> TITLES</span><span><b>${x.wins}</b> WINS</span><span><b>${x.poles}</b> POLES</span></div><span class="card-arrow">↗</span></button>`).join('')}</div>`);
 document.querySelectorAll('[data-legend]').forEach(b=>b.onclick=()=>archiveTransition(()=>legendDetail(b.dataset.legend)));
}
function legendDetail(id){
 const x=LEGENDS.find(v=>v.id===id); if(!x)return;
 archiveShell(x.name,`${x.tag} · ${x.years}`,`<button class="archive-back" onclick="go('legends')">← All legends</button><div class="archive-hero-detail"><div><div class="detail-label">LEGACY</div><h3>${x.name}</h3><p>${x.text}</p><p>${x.legacy}</p>${LEGEND_CHAMPIONSHIPS[x.id]?.length ? `<section class="championship-cabinet"><div class="section-label">WORLD CHAMPIONSHIPS</div><div class="championship-years">${LEGEND_CHAMPIONSHIPS[x.id].map(y=>`<span class="championship-year">${y}</span>`).join('')}</div></section>` : ''}</div><div class="stats-grid"><div><span>WORLD TITLES</span><strong>${x.titles}</strong></div><div><span>WINS</span><strong>${x.wins}</strong></div><div><span>POLES</span><strong>${x.poles}</strong></div><div><span>PODIUMS</span><strong>${x.podiums}</strong></div></div></div>`);
}
function archiveListPage(meta,data,type){
 archiveShell(meta[0],meta[1],`<div class="archive-grid archive-${type}">${data.map((x,i)=>`<button class="archive-card" data-archive-type="${type}" data-archive-id="${x.id||i}"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="archive-card-kicker">${x.year||x.years||x.team||''}</div><h3>${x.title||x.name||x.race}</h3><div class="archive-sub">${x.line||x.headline||x.stats||x.team||''}</div><p>${x.text}</p><span class="card-arrow">↗</span></button>`).join('')}</div>`);
 document.querySelectorAll('.archive-card').forEach(b=>b.onclick=()=>archiveTransition(()=>archiveDetail(type,b.dataset.archiveId)));
}

const CAR_COMPARE_DETAILS = {"mp44": {"engine": "Honda RA168E 1.5L V6 Turbo", "wins": "15 / 16", "poles": "15", "titles": "Drivers + Constructors"}, "fw14b": {"engine": "Renault RS4 3.5L V10", "wins": "10 / 16", "poles": "15", "titles": "Drivers + Constructors"}, "lotus79": {"engine": "Ford-Cosworth DFV 3.0L V8", "wins": "6", "poles": "10", "titles": "Drivers + Constructors"}, "f2004": {"engine": "Ferrari Tipo 053 3.0L V10", "wins": "15 / 18", "poles": "12", "titles": "Drivers + Constructors"}, "w11": {"engine": "Mercedes-AMG F1 M11 EQ Performance", "wins": "13 / 17", "poles": "15", "titles": "Drivers + Constructors"}, "rb9": {"engine": "Renault RS27 2.4L V8", "wins": "13 / 19", "poles": "11", "titles": "Drivers + Constructors"}, "mp413": {"engine": "Mercedes FO 110G 3.0L V10", "wins": "9 / 16", "poles": "12", "titles": "Drivers + Constructors"}, "f641": {"engine": "Ferrari Tipo 036 3.5L V12", "wins": "6 / 16", "poles": "3", "titles": "—"}};

function carsPage(){
  archiveShell('Iconic Cars','MACHINES THAT CHANGED FORMULA 1',
    `<div class="car-compare-launch"><button id="openCarCompare">Compare two cars ↗</button></div>
     <div class="archive-grid archive-car">${ICONIC_CARS.map((x,i)=>`<button class="archive-card" data-archive-type="car" data-archive-id="${x.id}"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="archive-card-kicker">${x.year}</div><h3>${x.name}</h3><div class="archive-sub">${x.team}</div><p>${x.text}</p><span class="card-arrow">↗</span></button>`).join('')}</div>`);
  document.getElementById('openCarCompare').onclick=openCarCompare;
  document.querySelectorAll('.archive-card').forEach(b=>b.onclick=()=>archiveTransition(()=>archiveDetail('car',b.dataset.archiveId)));
}

function openCarCompare(){
  let overlay=document.getElementById('carCompareOverlay');
  if(!overlay){
    overlay=document.createElement('div');
    overlay.id='carCompareOverlay';
    overlay.className='car-compare-overlay';
    overlay.innerHTML=`<div class="car-compare-shell">
      <div class="car-compare-head"><span>THE GRID / ICONIC CAR COMPARISON</span><button class="car-compare-close" aria-label="Close comparison">×</button></div>
      <div class="car-compare-selectors">
        <select id="compareCarA"></select><div class="car-compare-vs">versus</div><select id="compareCarB"></select>
      </div>
      <div class="car-compare-panels"><div class="car-compare-panel" id="comparePanelA"></div><div class="car-compare-panel" id="comparePanelB"></div></div>
    </div>`;
    document.body.appendChild(overlay);
    const options=ICONIC_CARS.map((c,i)=>`<option value="${i}">${c.name}</option>`).join('');
    overlay.querySelector('#compareCarA').innerHTML=options;
    overlay.querySelector('#compareCarB').innerHTML=options;
    overlay.querySelector('#compareCarB').selectedIndex=Math.min(3,ICONIC_CARS.length-1);
    overlay.querySelector('#compareCarA').onchange=renderCarCompare;
    overlay.querySelector('#compareCarB').onchange=renderCarCompare;
    overlay.querySelector('.car-compare-close').onclick=()=>overlay.classList.remove('open');
    overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.classList.remove('open')});
  }
  renderCarCompare();
  overlay.classList.add('open');
}

function renderCarCompare(){
  const overlay=document.getElementById('carCompareOverlay'); if(!overlay)return;
  const a=ICONIC_CARS[Number(overlay.querySelector('#compareCarA').value)];
  const b=ICONIC_CARS[Number(overlay.querySelector('#compareCarB').value)];
  const panel=(c)=>{
    const d=CAR_COMPARE_DETAILS[c.id]||{};
    return `<div><div class="car-compare-kicker">${c.year} · ${c.team}</div><h3>${c.name}</h3><div class="car-compare-drivers">${c.drivers}</div></div>
      <div class="car-compare-stats">
        <div class="car-compare-stat"><label>ENGINE</label><strong>${d.engine||'—'}</strong></div>
        <div class="car-compare-stat"><label>WINS</label><strong>${d.wins||'—'}</strong></div>
        <div class="car-compare-stat"><label>POLES</label><strong>${d.poles||'—'}</strong></div>
        <div class="car-compare-stat"><label>CHAMPIONSHIPS</label><strong>${d.titles||'—'}</strong></div>
      </div>`;
  };
  overlay.querySelector('#comparePanelA').innerHTML=panel(a);
  overlay.querySelector('#comparePanelB').innerHTML=panel(b);
}

function archiveDetail(type,id){
 const maps={rivalry:RIVALRIES,car:ICONIC_CARS,era:ERAS,race:RACES,historic:HISTORIC_TEAMS,moment:MOMENTS}; const x=maps[type].find((v,i)=>String(v.id||i)===String(id)); if(!x)return;
 const title=x.title||x.name||x.race; const kicker=x.years||x.year||x.team||'';
 archiveShell(title,`${type.toUpperCase()} · ${kicker}`,`<button class="archive-back" onclick="go('${({rivalry:'rivalries',car:'cars',era:'eras',race:'races',historic:'historic-teams',moment:'moments'})[type]}')">← Back</button><div class="archive-detail"><div class="archive-detail-main"><div class="detail-label">${x.line||x.headline||x.team||x.race||'THE STORY'}</div><h3>${title}</h3><p>${x.text}</p>${x.a?`<div class="duel"><span>${x.a}</span><b>VS</b><span>${x.b}</span></div>`:''}${x.stats?`<div class="archive-statline">${x.stats}</div>`:''}</div><div class="archive-side"><div class="detail-label">THE GRID / ARCHIVE</div><div class="archive-side-number">${x.year||x.years||'F1'}</div></div></div>`);
}
function championsPage(){
 archiveShell('Champions','1950–2026 · DRIVERS’ WORLD CHAMPIONSHIP',`<div class="champion-list">${CHAMPIONS.map(([year,name],i)=>`<div class="champion-row ${name==='In progress'?'current':''}"><span>${year}</span><strong>${name}</strong><small>${name==='In progress'?'SEASON IN PROGRESS':'WORLD CHAMPION'}</small></div>`).join('')}</div>`);
}
function recordsPage(){
 archiveShell('Records','ALL-TIME F1 NUMBERS',`<div class="record-grid">${RECORDS.map((x,i)=>`<article class="record-card"><div class="archive-index">${String(i+1).padStart(2,'0')}</div><div class="record-value">${x.value}</div><div class="record-label">${x.label}</div><strong>${x.holder}</strong><p>${x.note}</p></article>`).join('')}</div>`);
}

archiveInit();
home();

/* Intro session control — safe because CSS auto-exits independently. */
try{
  const intro=document.getElementById('introSequence');
  if(sessionStorage.getItem('theGridIntroSeen')==='1'){
    intro?.classList.add('skip');
  }else{
    sessionStorage.setItem('theGridIntroSeen','1');
  }
}catch(e){
  /* No action needed: CSS fallback dismisses the intro. */
}
